-- Serana canonical catalog source
--
-- Supabase becomes the only runtime authority for product content, selling
-- prices, variants, recipes and combo configuration. The public web and ERP
-- must consume these rows rather than bundled catalog snapshots.

alter table catalog.products
  add column if not exists benefits text[] not null default '{}'::text[],
  add column if not exists health_benefit text,
  add column if not exists observation text,
  add column if not exists portions text,
  add column if not exists public_ingredients text[] not null default '{}'::text[],
  add column if not exists option_groups jsonb,
  add column if not exists combo_configuration jsonb;

comment on column catalog.products.price is
  'Canonical default selling price. Kept transactionally equal to the active default product_checkout_prices row.';
comment on column catalog.products.public_ingredients is
  'Customer-facing ingredient labels. Operational quantities remain canonical in catalog.product_recipes.';
comment on column catalog.products.combo_configuration is
  'Canonical storefront combo selection rules as validated JSON.';

