update catalog.products p
set
  name = coalesce(nullif(source.data->>'name', ''), p.name),
  description = coalesce(source.data->>'description', p.description),
  benefits = coalesce(
    array(select jsonb_array_elements_text(source.data->'benefits')),
    '{}'::text[]
  ),
  health_benefit = nullif(source.data->>'health_benefit', ''),
  observation = nullif(source.data->>'observation', ''),
  portions = nullif(source.data->>'portions', ''),
  public_ingredients = coalesce(
    array(select jsonb_array_elements_text(source.data->'public_ingredients')),
    '{}'::text[]
  ),
  option_groups = case
    when jsonb_typeof(source.data->'option_groups') = 'object'
      then source.data->'option_groups'
    else null
  end,
  updated_at = now()
from source
where p.slug = source.data->>'slug';

