insert into catalog.product_checkout_prices (
  product_id,
  variant_label,
  price,
  is_default,
  sort_order,
  active,
  updated_at
)
select
  p.id,
  source.variant_label,
  source.price,
  source.is_default,
  source.sort_order,
  true,
  now()
from source
join catalog.products p on p.slug = source.slug
on conflict (product_id, variant_key) do update
set
  price = greatest(catalog.product_checkout_prices.price, excluded.price),
  is_default = excluded.is_default,
  sort_order = excluded.sort_order,
  active = true,
  updated_at = now();

-- Every active product receives one default price. Existing disagreements use
-- the highest value, per the approved catalog reconciliation rule.
insert into catalog.product_checkout_prices (
  product_id,
  variant_label,
  price,
  is_default,
  sort_order,
  active,
  updated_at
)
select p.id, null, p.price, true, 0, true, now()
from catalog.products p
where p.active
on conflict (product_id, variant_key) do update
set
  price = greatest(catalog.product_checkout_prices.price, excluded.price),
  is_default = true,
  sort_order = 0,
  active = true,
  updated_at = now();

update catalog.products p
set price = cp.price,
    updated_at = now()
from catalog.product_checkout_prices cp
where cp.product_id = p.id
  and cp.active
  and cp.is_default
  and p.price is distinct from cp.price;

