set combo_configuration = source.data->'configuration',
    updated_at = now()
from source
where p.slug = source.data->>'slug';

-- Resolve the catalog exceptions approved during the audit.
update catalog.products
set name = 'Jugo de naranja x6',
    updated_at = now()
where slug = 'jugo-naranja';

update catalog.products
set active = false,
    updated_at = now()
where slug = 'perejil-x-200-gr';

update catalog.product_recipes pr
set ingredient_id = papelillo.id,
    unit_id = papelillo.unit_id
from catalog.products p,
     catalog.ingredients hass,
     catalog.ingredients papelillo
where pr.product_id = p.id
  and pr.ingredient_id = hass.id
  and p.slug = 'aguacate-papelillo'
  and lower(hass.name) = 'aguacate hass'
  and lower(papelillo.name) = 'aguacate papelillo';

with recipe_seed(ingredient_name, quantity, waste_factor) as (
  values
    ('Coco', 0.500::numeric, 0.000::numeric),
    ('Bowls 32 oz', 1.000::numeric, 0.000::numeric),
    ('Tapas 32 16 oz', 1.000::numeric, 0.000::numeric),
    ('Etiquetas frutas 32-16 oz', 1.000::numeric, 0.000::numeric),
    ('Sticker mantener refrigerado', 1.000::numeric, 0.000::numeric),
    ('Stickers consumir antes de', 1.000::numeric, 0.000::numeric)
)
insert into catalog.product_recipes (
  product_id,
  ingredient_id,
  quantity,
  unit_id,
  waste_factor
)
select
  p.id,
  i.id,
  recipe_seed.quantity,
  i.unit_id,
  recipe_seed.waste_factor
from recipe_seed
join catalog.ingredients i on lower(i.name) = lower(recipe_seed.ingredient_name)
join catalog.products p on p.slug = 'coco'
on conflict (product_id, ingredient_id) do update
set
  quantity = excluded.quantity,
  unit_id = excluded.unit_id,
  waste_factor = excluded.waste_factor;

-- Public storefront view. New catalog columns are appended so existing clients
-- keep their stable column order.
create or replace view public.products_public_view as
select
  p.id,
  p.slug,
  p.name,
  p.description,
  p.price,
  p.image_url,
  coalesce(p.gallery_urls, '{}'::text[]) as gallery_urls,
  p.active,
  pc.code as category_code,
  pc.name as category_name,
  p.created_at,
  p.updated_at,
  coalesce(p.benefits, '{}'::text[]) as benefits,
  p.health_benefit,
  p.observation,
  p.portions,
  coalesce(p.public_ingredients, '{}'::text[]) as public_ingredients,
  p.option_groups,
  p.combo_configuration
from catalog.products p
left join catalog.product_categories pc on pc.id = p.category_id
where p.active = true;

create or replace view public.products_admin_view as
select
  p.id,
  p.slug,
  p.name,
  p.description,
  p.price,
  p.active,
  p.image_url,
  p.category_id,
  pc.code as category_code,
  pc.name as category_name,
  p.created_at,
  p.updated_at,
  coalesce(p.gallery_urls, '{}'::text[]) as gallery_urls,
  coalesce(p.benefits, '{}'::text[]) as benefits,
  p.health_benefit,
  p.observation,
  p.portions,
  coalesce(p.public_ingredients, '{}'::text[]) as public_ingredients,
  p.option_groups,
  p.combo_configuration,
  coalesce(
    (
      select jsonb_agg(
        jsonb_build_object(
          'label', cp.variant_label,
          'price', cp.price,
          'is_default', cp.is_default,
          'sort_order', cp.sort_order
        )
        order by cp.sort_order, cp.variant_label nulls first
      )
      from catalog.product_checkout_prices cp
      where cp.product_id = p.id and cp.active
    ),
    '[]'::jsonb
  ) as checkout_prices
from catalog.products p
left join catalog.product_categories pc on pc.id = p.category_id;

create or replace view public.recipe_products_view as
select
  p.id,
  p.slug,
  p.name,
  p.description,
  p.price,
  p.active,
  p.category_id,
  pc.code as category_code,
  pc.name as category_name,
  count(pr.id)::int as recipe_item_count,
  coalesce(
    sum(pr.quantity * (1 + pr.waste_factor) * coalesce(i.base_unit_cost, 0)),
    0
  )::numeric(12,2) as estimated_recipe_cost,
  case
    when p.price > 0 then round(
      (
        coalesce(sum(pr.quantity * (1 + pr.waste_factor) * coalesce(i.base_unit_cost, 0)), 0)
        / p.price
      ) * 100,
      2
    )
    else 0
  end as estimated_cost_percent,
  null::timestamptz as recipe_updated_at,
  coalesce(p.benefits, '{}'::text[]) as benefits,
  p.health_benefit,
  p.observation,
  p.portions,
  coalesce(p.public_ingredients, '{}'::text[]) as public_ingredients,
  p.option_groups,
  p.combo_configuration,
  coalesce(
    (
      select jsonb_agg(
        jsonb_build_object(
          'label', cp.variant_label,
          'price', cp.price,
          'is_default', cp.is_default,
          'sort_order', cp.sort_order
        )
        order by cp.sort_order, cp.variant_label nulls first
      )
      from catalog.product_checkout_prices cp
      where cp.product_id = p.id and cp.active
    ),
    '[]'::jsonb
  ) as checkout_prices
from catalog.products p
left join catalog.product_categories pc on pc.id = p.category_id
left join catalog.product_recipes pr on pr.product_id = p.id
left join catalog.ingredients i on i.id = pr.ingredient_id
group by p.id, pc.id
order by p.name;

grant select on public.products_public_view to anon, authenticated;
grant select on public.products_admin_view to authenticated;
grant select on public.recipe_products_view to authenticated;

create or replace function public.upsert_product(payload jsonb)
returns public.products_admin_view
language plpgsql
security definer
set search_path = public, catalog
as $$
declare
  v_id uuid := nullif(payload->>'id', '')::uuid;
  v_name text := trim(payload->>'name');
  v_slug text := nullif(trim(payload->>'slug'), '');
  v_description text := nullif(trim(coalesce(payload->>'description', '')), '');
  v_price numeric := (payload->>'price')::numeric;
  v_active boolean := coalesce((payload->>'active')::boolean, true);
  v_image_url text := nullif(payload->>'image_url', '');
  v_gallery_urls text[] := coalesce(
    array(
      select distinct trim(value)
      from jsonb_array_elements_text(coalesce(payload->'gallery_urls', '[]'::jsonb)) value
      where trim(value) <> '' and trim(value) is distinct from coalesce(v_image_url, '')
    ),
    '{}'::text[]
  );
  v_category_id uuid := nullif(payload->>'category_id', '')::uuid;
  v_benefits text[] := coalesce(
    array(
      select trim(value)
      from jsonb_array_elements_text(coalesce(payload->'benefits', '[]'::jsonb)) value
      where trim(value) <> ''
    ),
    '{}'::text[]
  );
  v_public_ingredients text[] := coalesce(
    array(
      select trim(value)
      from jsonb_array_elements_text(coalesce(payload->'public_ingredients', '[]'::jsonb)) value
      where trim(value) <> ''
    ),
    '{}'::text[]
  );
  v_health_benefit text := nullif(trim(coalesce(payload->>'health_benefit', '')), '');
  v_observation text := nullif(trim(coalesce(payload->>'observation', '')), '');
  v_portions text := nullif(trim(coalesce(payload->>'portions', '')), '');
  v_option_groups jsonb := case
    when jsonb_typeof(payload->'option_groups') = 'object' then payload->'option_groups'
    else null
  end;
  v_combo_configuration jsonb := case
    when jsonb_typeof(payload->'combo_configuration') = 'object' then payload->'combo_configuration'
    else null
  end;
  v_variant jsonb;
  v_variant_label text;
  v_variant_price numeric;
  v_sort_order integer := 1;
  v_row public.products_admin_view;
begin
  perform public._assert_catalog_writer();

  if v_name is null or length(v_name) < 2 then
    raise exception 'name is required (min 2 chars)' using errcode = '22023';
  end if;
  if v_slug is null or v_slug !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' then
    raise exception 'valid slug is required' using errcode = '22023';
  end if;
  if v_price is null or v_price < 0 then
    raise exception 'price must be >= 0' using errcode = '22023';
  end if;

  if v_id is null then
    insert into catalog.products (
      slug, name, description, price, active, image_url, gallery_urls, category_id,
      benefits, health_benefit, observation, portions, public_ingredients,
      option_groups, combo_configuration
    ) values (
      v_slug, v_name, v_description, v_price, v_active, v_image_url, v_gallery_urls, v_category_id,
      v_benefits, v_health_benefit, v_observation, v_portions, v_public_ingredients,
      v_option_groups, v_combo_configuration
    )
    returning id into v_id;
  else
    update catalog.products
    set
      slug = v_slug,
      name = v_name,
      description = v_description,
      price = v_price,
      active = v_active,
      image_url = v_image_url,
      gallery_urls = v_gallery_urls,
      category_id = v_category_id,
      benefits = v_benefits,
      health_benefit = v_health_benefit,
      observation = v_observation,
      portions = v_portions,
      public_ingredients = v_public_ingredients,
      option_groups = v_option_groups,
      combo_configuration = v_combo_configuration,
      updated_at = now()
    where id = v_id;
  end if;

  if not found then
    raise exception 'product not found: %', v_id using errcode = '22023';
  end if;

  insert into catalog.product_checkout_prices (
    product_id, variant_label, price, is_default, sort_order, active, updated_at
  ) values (
    v_id, null, v_price, true, 0, true, now()
  )
  on conflict (product_id, variant_key) do update
  set price = excluded.price,
      is_default = true,
      sort_order = 0,
      active = true,
      updated_at = now();

  update catalog.product_checkout_prices
  set active = false,
      updated_at = now()
  where product_id = v_id
    and variant_label is not null;

  for v_variant in
    select value from jsonb_array_elements(coalesce(payload->'variants', '[]'::jsonb))
  loop
    v_variant_label := nullif(trim(v_variant->>'label'), '');
    v_variant_price := (v_variant->>'price')::numeric;
    if v_variant_label is null or v_variant_price is null or v_variant_price < 0 then
      raise exception 'every variant requires label and price >= 0' using errcode = '22023';
    end if;

    insert into catalog.product_checkout_prices (
      product_id, variant_label, price, is_default, sort_order, active, updated_at
    ) values (
      v_id, v_variant_label, v_variant_price, false, v_sort_order, true, now()
    )
    on conflict (product_id, variant_key) do update
    set price = excluded.price,
        is_default = false,
        sort_order = excluded.sort_order,
        active = true,
        updated_at = now();

    v_sort_order := v_sort_order + 1;
  end loop;

  select * into v_row
  from public.products_admin_view
  where id = v_id;
  return v_row;
end;
$$;

revoke all on function public.upsert_product(jsonb) from public;
grant execute on function public.upsert_product(jsonb) to authenticated;

drop function if exists public.update_recipe_product_content(uuid, text, text);

create or replace function public.update_recipe_product_content(
  p_product_id uuid,
  p_name text,
  p_description text,
  p_price numeric
)
returns public.recipe_products_view
language plpgsql
security definer
set search_path = public, catalog
as $$
declare
  v_name text := trim(coalesce(p_name, ''));
  v_row public.recipe_products_view;
begin
  perform public._assert_catalog_writer();

  if p_product_id is null then
    raise exception 'product_id is required' using errcode = '22023';
  end if;
  if length(v_name) < 2 then
    raise exception 'name is required (min 2 chars)' using errcode = '22023';
  end if;
  if p_price is null or p_price < 0 then
    raise exception 'price must be >= 0' using errcode = '22023';
  end if;

  update catalog.products
  set name = v_name,
      description = nullif(trim(coalesce(p_description, '')), ''),
      price = p_price,
      updated_at = now()
  where id = p_product_id;

  if not found then
    raise exception 'product not found: %', p_product_id using errcode = '22023';
  end if;

  insert into catalog.product_checkout_prices (
    product_id, variant_label, price, is_default, sort_order, active, updated_at
  ) values (
    p_product_id, null, p_price, true, 0, true, now()
  )
  on conflict (product_id, variant_key) do update
  set price = excluded.price,
      is_default = true,
      sort_order = 0,
      active = true,
      updated_at = now();

  select * into v_row
  from public.recipe_products_view
  where id = p_product_id;
  return v_row;
end;
$$;

revoke all on function public.update_recipe_product_content(uuid, text, text, numeric) from public;
grant execute on function public.update_recipe_product_content(uuid, text, text, numeric) to authenticated;

alter table catalog.product_checkout_prices
  drop constraint if exists product_checkout_prices_default_shape;
alter table catalog.product_checkout_prices
  add constraint product_checkout_prices_default_shape check (
    (is_default and variant_label is null)
    or (not is_default and variant_label is not null)
  ) not valid;
alter table catalog.product_checkout_prices
  validate constraint product_checkout_prices_default_shape;

create unique index if not exists uq_active_product_name_normalized
  on catalog.products (lower(trim(name)))
  where active;

create unique index if not exists uq_checkout_variant_label_normalized
  on catalog.product_checkout_prices (
    product_id,
    lower(regexp_replace(trim(variant_label), '\s+', ' ', 'g'))
  )
  where active and variant_label is not null;

create or replace function catalog.enforce_canonical_product_price()
returns trigger
language plpgsql
security definer
set search_path = catalog
as $$
declare
  v_product_id uuid;
  v_product catalog.products%rowtype;
  v_default_count integer;
  v_default_price numeric;
begin
  if tg_table_name = 'products' then
    v_product_id := coalesce(new.id, old.id);
  else
    v_product_id := coalesce(new.product_id, old.product_id);
  end if;

  select * into v_product
  from catalog.products
  where id = v_product_id;

  if not found or not v_product.active then
    return null;
  end if;

  select count(*), max(price)
  into v_default_count, v_default_price
  from catalog.product_checkout_prices
  where product_id = v_product_id
    and active
    and is_default;

  if v_default_count <> 1 or v_default_price <= 0 then
    raise exception 'active product % requires one positive default selling price', v_product.slug;
  end if;
  if v_product.price is distinct from v_default_price then
    raise exception 'canonical price mismatch for product %: catalog %, checkout %',
      v_product.slug, v_product.price, v_default_price;
  end if;

  return null;
end;
$$;

drop trigger if exists canonical_product_price_on_product on catalog.products;
create constraint trigger canonical_product_price_on_product
after insert or update on catalog.products
deferrable initially deferred
for each row execute function catalog.enforce_canonical_product_price();

drop trigger if exists canonical_product_price_on_checkout on catalog.product_checkout_prices;
create constraint trigger canonical_product_price_on_checkout
after insert or update or delete on catalog.product_checkout_prices
deferrable initially deferred
for each row execute function catalog.enforce_canonical_product_price();

